class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: list[str]) -> int:
        m, n = len(beginWord), len(wordList)
        graph = [set() for _ in range(m)]

        for i in range(m):
            for j in range(n):
                graph[i].add(wordList[j][i])


        queue = deque([beginWord])
        dist = {beginWord: 1}
        seen = set(queue)
        dictionary = set(wordList)

        def transform(word):
            neis = []
            node = list(word)
            for i in range(m):
                origin = node[i]
                for letter in graph[i]:
                    if letter != origin:
                        node[i] = letter
                        neis.append(''.join(node))
                node[i] = origin
            return neis

        while queue:
            k = len(queue)
            for _ in range(k):
                word = queue.popleft()
                if word == endWord:
                    return dist[word]

                for trans in transform(word):
                    if trans in dictionary and trans not in seen:
                        dist[trans] = dist[word] + 1
                        seen.add(trans)
                        queue.append(trans)
        return 0
